# compute geodesic distances over 3-cells from adjacent sample components (source IDs)
from collections import deque
coords=[tuple(x) for x in np.argwhere(arr==3)]
coordset=set(coords)
distances=[]
for pts,mode in srcs:
 starts=set()
 for r,c in pts:
  for dr,dc in [(1,0),(-1,0),(0,1),(0,-1)]:
   q=(int(r+dr),int(c+dc))
   if q in coordset: starts.add(q)
 d={q:0 for q in starts}; Q=deque(starts)
 while Q:
  q=Q.popleft()
  for dr,dc in [(1,0),(-1,0),(0,1),(0,-1)]:
   z=(q[0]+dr,q[1]+dc)
   if z in coordset and z not in d: d[z]=d[q]+1; Q.append(z)
 distances.append(d)
 print(mode,len(starts),starts)
geodesic=arr.copy()
for q in coords:
 ds=[d.get(q,999) for d in distances]
 mi=min(ds)
 ix=next(i for i,x in enumerate(ds) if x==mi)
 geodesic[q]=srcs[ix][1]
print('\n'.join(' '.join(map(str,row)) for row in geodesic))

# determine color-distances min by colors from 4 source groups
color_d={}
for q in coords:
 color_d[q]={}
 for d,(pts,mode) in zip(distances,srcs):
  v=d.get(q,999)
  color_d[q][mode]=min(v,color_d[q].get(mode,999))
out_tie=arr.copy(); ties=[]
for q in coords:
 md=min(color_d[q].values()); winning=[col for col,d in color_d[q].items() if d==md]
 if len(winning)>1: ties.append(q)
 else: out_tie[q]=winning[0]
print('ties',ties)
print('\n'.join(' '.join(map(str,row)) for row in out_tie))

